import json
import re
import pandas as pd


_NUMERIC_RE = re.compile(r"[-+]?(?:\d*\.\d+|\d+)(?:[eE][-+]?\d+)?")

def _double_value(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return float(value) * 2.0
    if isinstance(value, str):
        match = _NUMERIC_RE.search(value)
        if match:
            return float(match.group(0)) * 2.0
        return value
    if isinstance(value, list):
        return [_double_value(item) for item in value]
    if isinstance(value, tuple):
        return [_double_value(item) for item in value]
    return value


def task_func(json_str):
    if not isinstance(json_str, str) or not json_str.strip():
        return pd.DataFrame()

    try:
        data = json.loads(json_str)
    except Exception:
        return pd.DataFrame()

    if not isinstance(data, dict) or not data:
        return pd.DataFrame()

    normalized = {}
    for key, value in data.items():
        if isinstance(value, dict):
            return pd.DataFrame()
        normalized[key] = _double_value(value)

    list_lengths = []
    for value in normalized.values():
        if isinstance(value, (list, tuple)):
            list_lengths.append(len(value))

    if not list_lengths:
        return pd.DataFrame([normalized])

    if any(length == 0 for length in list_lengths):
        return pd.DataFrame()

    target_len = max(list_lengths)
    valid_lengths = {1, target_len}
    if any(length not in valid_lengths for length in list_lengths):
        return pd.DataFrame()

    frame_data = {}
    for key, value in normalized.items():
        if isinstance(value, tuple):
            value = list(value)

        if isinstance(value, list):
            if len(value) == target_len:
                frame_data[key] = value
            elif len(value) == 1:
                frame_data[key] = value * target_len
            else:
                return pd.DataFrame()
        else:
            frame_data[key] = [value] * target_len

    return pd.DataFrame(frame_data)
